/* Minimal local Bootstrap modal behavior used by this application. */
(function () {
  'use strict';
  function getTarget(trigger) {
    var selector = trigger.getAttribute('data-bs-target') || trigger.getAttribute('href');
    if (!selector || selector === '#') return null;
    try { return document.querySelector(selector); } catch (e) { return null; }
  }
  function closeModal(modal) {
    if (!modal) return;
    modal.classList.remove('show');
    modal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
    var backdrop = document.querySelector('.modal-backdrop');
    if (backdrop) backdrop.remove();
  }
  function openModal(modal) {
    if (!modal) return;
    document.querySelectorAll('.modal.show').forEach(closeModal);
    modal.classList.add('show');
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
    var backdrop = document.createElement('div');
    backdrop.className = 'modal-backdrop fade show';
    backdrop.addEventListener('click', function () { closeModal(modal); });
    document.body.appendChild(backdrop);
  }
  document.addEventListener('click', function (event) {
    var trigger = event.target.closest('[data-bs-toggle="modal"]');
    if (trigger) {
      event.preventDefault();
      openModal(getTarget(trigger));
      return;
    }
    var dismiss = event.target.closest('[data-bs-dismiss="modal"]');
    if (dismiss) {
      event.preventDefault();
      closeModal(dismiss.closest('.modal'));
    }
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      var modal = document.querySelector('.modal.show');
      if (modal) closeModal(modal);
    }
  });
  window.bootstrap = { Modal: { getOrCreateInstance: function (element) { return { show: function () { openModal(element); }, hide: function () { closeModal(element); } }; } } };
})();
